func (r *recordResource) Schema(_ context.Context, _ resource.SchemaRequest, resp *resource.SchemaResponse) {
    resp.Schema = schema.Schema{
        Attributes: map[string]schema.Attribute{
            "id":   schema.StringAttribute{Computed: true,
                PlanModifiers: []planmodifier.String{stringplanmodifier.UseStateForUnknown()}},
            "name": schema.StringAttribute{Required: true,
                PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
            "ttl":  schema.Int64Attribute{Optional: true, Computed: true,
                Validators: []validator.Int64{int64validator.Between(60, 86400)}},
        },
    }
}

func (r *recordResource) Read(ctx context.Context, req resource.ReadRequest, resp *resource.ReadResponse) {
    var st recordModel
    resp.Diagnostics.Append(req.State.Get(ctx, &st)...)
    rec, err := r.client.GetRecord(ctx, st.ID.ValueString())
    if errors.Is(err, client.ErrNotFound) {
        resp.State.RemoveResource(ctx)   // drifted away → recreate on next plan
        return
    }
    if err != nil { resp.Diagnostics.AddError("read failed", err.Error()); return }
    st.TTL = types.Int64Value(rec.TTL)
    resp.Diagnostics.Append(resp.State.Set(ctx, &st)...)
}

func TestAccRecord_basic(t *testing.T) {
    resource.Test(t, resource.TestCase{
        ProtoV6ProviderFactories: testProviders,
        CheckDestroy:             testCheckRecordDestroyed,
        Steps: []resource.TestStep{
            {Config: cfg(300), Check: resource.TestCheckResourceAttr("acmedns_record.a", "ttl", "300")},
            {Config: cfg(600), Check: resource.TestCheckResourceAttr("acmedns_record.a", "ttl", "600")},
            {ResourceName: "acmedns_record.a", ImportState: true, ImportStateVerify: true},
        },
    })
}

